        shayariItem(368, "जब सारे रास्ते बंद हो जाते हैं शहर में,\nतब सिर्फ़ मयख़ाने का दरवाज़ा खुला मिलता है।", "_ शायरी", cat, "दरवाज़ा"),
        shayariItem(369, "लड़खड़ाता हूँ तो लोग शराबी समझते हैं,\nउन्हें क्या पता दिल के ज़ख़्मों से पैर डगमगाते हैं।", "_ शायरी", cat, "दर्द"),
        shayariItem(370, "कुछ रिश्ते इतने कड़वे हो गए ज़िंदगी में,\nकि उनके आगे शराब भी मीठी लगने लगी।", "_ शायरी", cat, "रिश्ते"),
        shayariItem(371, "चाँद भी आज मेरे गिलास में झाँक रहा था,\nशायद वो भी किसी की जुदाई में रात भर जागा था।", "_ शायरी", cat, "चाँद"),
        shayariItem(372, "साक़ी ज़रा बड़ा गिलास ला आज हिसाब लंबा है,\nबरसों की यादें एक ही रात में भुला देनी हैं।", "_ शायरी", cat, "हिसाब"),
        shayariItem(373, "नशे की आदत नहीं थी हमें कभी,\nतेरी मोहब्बत की खाली जगह भरने को ये सहारा लिया।", "_ शायरी", cat, "सहारा"),
        shayariItem(374, "महफ़िल में सब हँस रहे थे मेरे लतीफ़ों पर,\nबस कोने में बैठा साक़ी मेरी आँखों का दर्द पढ़ गया।", "_ शायरी", cat, "महफ़िल"),
        shayariItem(375, "जाम ख़त्म हुआ तो हक़ीक़त फिर सामने आ गई,\nवही खाली कमरा, वही रात और वही तेरी कमी।", "_ शायरी", cat, "कमी"),
        shayariItem(376, "पीते हैं हम ताकि दुनिया के ताने न सुनें,\nऔर दुनिया कहती है पीने की वजह से बर्बाद हो गए।", "_ शायरी", cat, "ताने"),
        shayariItem(377, "दिल की आग बुझाने को पी थी थोड़ी सी,\nकमबख़्त इसने तो यादों को और भड़का दिया।", "_ शायरी", cat, "आग"),
        shayariItem(378, "कभी जो हम महफ़िल की जान हुआ करते थे,\nआज एक कोने में चुपचाप जाम घूँटते रहते हैं।", "_ शायरी", cat, "ख़ामोशी"),
        shayariItem(379, "बोतल पर लिखा था सेहत के लिए हानिकारक,\nकाश तेरे माथे पर भी लिखा होता दिल के लिए ख़तरनाक।", "_ शायरी", cat, "तंज"),
        shayariItem(380, "रंगीन शीशे में आज अपना अक्स धुंधला दिखा,\nबिल्कुल वैसा ही धुंधला जैसा तेरा प्यार निकला।", "_ शायरी", cat, "अक्स"),
        shayariItem(381, "नशा तो हमें तेरी बातों का आज भी है,\nशराब तो बस लोगों को दिखाने का एक बहाना है।", "_ शायरी", cat, "बहाना"),
        shayariItem(382, "एक घूँट तेरी ख़ुशियों के नाम पीता हूँ,\nएक घूँट अपने टूटे ख़्वाबों के नाम।", "_ शायरी", cat, "ख़्वाब"),
        shayariItem(383, "साक़ी ने आज बिल नहीं लिया मुझसे,\nकहा इतना दर्द लेकर घूमते हो यही काफ़ी है।", "_ शायरी", cat, "दर्द"),
        shayariItem(384, "सारी रात जाम से बातें होती रहीं,\nसुबह आईने ने कहा थोड़ा संभल जा मेरे यार।", "_ शायरी", cat, "आईना"),
        shayariItem(385, "इश्क़ और शराब दोनों एक जैसे ही होते हैं,\nशुरू में बड़ा मज़ा आता है बाद में सिर्फ़ सिरदर्द।", "_ शायरी", cat, "इश्क़"),
        shayariItem(386, "मैख़ाने की मिट्टी में भी कितनी वफ़ा है,\nगिरते हैं तो चुपचाप संभाल लेती है।", "_ शायरी", cat, "वफ़ा"),
        shayariItem(387, "हमने तो अपने आँसुओं को भी जाम में मिला दिया,\nताकि दर्द का स्वाद थोड़ा हल्का हो जाए।", "_ शायरी", cat, "आँसू"),
        shayariItem(388, "जो मज़ा दो दोस्तों के साथ एक बोतल बाँटने में है,\nवो अमीरी के किसी महल में भी नहीं मिलता।", "_ शायरी", cat, "दोस्ती"),
        shayariItem(389, "ज़िंदगी भी एक अधूरे पैमाने जैसी हो गई है,\nन पूरी भरती है और न ही ख़ाली छोड़ी जाती है।", "_ शायरी", cat, "ज़िंदगी"),
        shayariItem(390, "होश में आए तो फिर वही सवाल सताएगा,\nइसलिए आज रात भर नशे में ही रहने दो।", "_ शायरी", cat, "सवाल"),
        shayariItem(391, "तेरे नाम का एक प्याला आज भी अलग रखता हूँ,\nक्या पता किस मोड़ पर यादें मेहमान बनकर आ जाएँ।", "_ शायरी", cat, "मेहमान"),
        shayariItem(392, "शराबी आँखें भी कभी-कभी सच देख लेती हैं,\nजो होश वाले चश्मे लगाकर भी नहीं देख पाते।", "_ शायरी", cat, "नज़र"),
        shayariItem(393, "साक़ी के हाथ में जब तक सुराही है,\nतब तक हर टूटे दिल को थोड़ी पनाह मिली है।", "_ शायरी", cat, "पनाह"),
        shayariItem(394, "हम तो प्यास बुझाने आए थे दरिया के किनारे,\nन जाने कब हाथों में मय का प्याला आ गया।", "_ शायरी", cat, "प्यास"),
        shayariItem(395, "ग़मों का बोझ कुछ यूँ हल्का कर लेते हैं हम,\nथोड़ी चाय दिन में और थोड़ा जाम शाम को पी लेते हैं।", "_ शायरी", cat, "सुकून"),
        shayariItem(396, "न जाने कौन सी सज़ा काट रहा हूँ मैं,\nहर शाम एक नया ज़हर मुस्कुराकर पी रहा हूँ।", "_ शायरी", cat, "सज़ा"),
        shayariItem(397, "लोग पूछते हैं इतना क्यों पीते हो यार,\nहम कहते हैं ताकि दिल की धड़कनें थोड़ी धीमी रहें।", "_ शायरी", cat, "धड़कन"),
        shayariItem(398, "टूटे हुए गिलास से भी लोग संभलकर रहते हैं,\nबस टूटा हुआ दिल ही किसी को चुभता नहीं दिखता।", "_ शायरी", cat, "शीशा"),
        shayariItem(399, "चलो एक आख़िरी जाम और भर दो साक़ी,\nकल से फिर ज़िंदगी की वही कड़वी हक़ीक़त जीनी है।", "_ शायरी", cat, "हक़ीक़त"),
        shayariItem(400, "मैख़ाने की आख़िरी बत्ती बुझने तक बैठे रहे हम,\nशायद कोई आवाज दे दे पर सन्नाटा ही मिला।", "_ शायरी", cat, "आख़िरी जाम")
    )
}
